package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializationConfig;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.BeanPropertyDefinition;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.impl.StdDeserializationContext;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_filterBeanProps_TriageGen1Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private BeanDeserializerBuilder builder;
    private DeserializationConfig config;

    @Before
    public void setUp() {
        // BeanDeserializerFactory constructor requires DeserializerFactoryConfig
        // Since we are testing a protected method, we use a spy or a subclass if needed, 
        // but here we can use Mockito to spy on the real factory.
        factory = spy(new BeanDeserializerFactory(null));
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        builder = mock(BeanDeserializerBuilder.class);
        config = mock(DeserializationConfig.class);

        when(ctxt.getConfig()).thenReturn(config);
    }

    /**
     * Helper to access the protected method via reflection or by making the test class 
     * part of the same package. Since the instruction asks for the specific package, 
     * we assume access is available.
     */
    @SuppressWarnings("unchecked")
    protected List<BeanPropertyDefinition> invokeFilterBeanProps(
            DeserializationContext ctxt,
            BeanDescription beanDesc,
            BeanDeserializerBuilder builder,
            List<BeanPropertyDefinition> propDefsIn,
            Set<String> ignored) throws Exception {
        return factory.filterBeanProps(ctxt, beanDesc, builder, propDefsIn, ignored);
    }

    @Test
    public void testFilterBeanProps_AllIgnoredBySet() throws Exception {
        BeanPropertyDefinition prop1 = mock(BeanPropertyDefinition.class);
        when(prop1.getName()).thenReturn("prop1");
        BeanPropertyDefinition prop2 = mock(BeanPropertyDefinition.class);
        when(prop2.getName()).thenReturn("prop2");

        List<BeanPropertyDefinition> input = Arrays.asList(prop1, prop2);
        Set<String> ignored = new HashSet<>(Collections.singletonList("prop1"));

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertEquals(1, result.size());
        assertEquals("prop2", result.get(0).getName());
        verify(builder, never()).addIgnorable(anyString());
    }

    @Test
    public void testFilterBeanProps_ConstructorParameter_NeverSkipped() throws Exception {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("id");
        when(prop.hasConstructorParameter()).thenReturn(true);

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        // Even if isIgnorableType would return true, constructor params are skipped
        doReturn(true).when(factory).isIgnorableType(any(), any(), any(), any());

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertEquals(1, result.size());
        verify(builder, never()).addIgnorable(anyString());
    }

    @Test
    public void testFilterBeanProps_SetterProperty_IgnorableType() throws Exception {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("someProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(true);

        BeanDeserializer.Setter setter = mock(BeanDeserializer.Setter.class);
        when(prop.getSetter()).thenReturn(setter);
        when(setter.getRawParameterType(0)).thenReturn(String.class);

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        // Mock isIgnorableType to return true
        doReturn(true).when(factory).isIgnorableType(eq(config), eq(beanDesc), eq(String.class), anyMap());

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertTrue(result.isEmpty());
        verify(builder).addIgnorable("someProp");
    }

    @Test
    public void testFilterBeanProps_FieldProperty_IgnorableType() throws Exception {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("someField");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(false);
        when(prop.hasField()).thenReturn(true);

        BeanDeserializer.Field field = mock(BeanDeserializer.Field.class);
        when(prop.getField()).thenReturn(field);
        when(field.getRawType()).thenReturn(Integer.class);

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        doReturn(true).when(factory).isIgnorableType(eq(config), eq(beanDesc), eq(Integer.class), anyMap());

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertTrue(result.isEmpty());
        verify(builder).addIgnorable("someField");
    }

    @Test
    public void testFilterBeanProps_ValidProperty_Keep() throws Exception {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("validProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(true);

        BeanDeserializer.Setter setter = mock(BeanDeserializer.Setter.class);
        when(prop.getSetter()).thenReturn(setter);
        when(setter.getRawParameterType(0)).thenReturn(Double.class);

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        // Mock isIgnorableType to return false
        doReturn(false).when(factory).isIgnorableType(eq(config), eq(beanDesc), eq(Double.class), anyMap());

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertEquals(1, result.size());
        assertEquals("validProp", result.get(0).getName());
        verify(builder, never()).addIgnorable(anyString());
    }

    @Test
    public void testFilterBeanProps_NullType_Keep() throws Exception {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("nullTypeProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(true);

        BeanDeserializer.Setter setter = mock(BeanDeserializer.Setter.class);
        when(prop.getSetter()).thenReturn(setter);
        // Return null for raw type
        when(setter.getRawParameterType(0)).thenReturn(null);

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertEquals(1, result.size());
        verify(builder, never()).addIgnorable(anyString());
    }

    @Test
    public void testFilterBeanProps_EmptyInput() throws Exception {
        List<BeanPropertyDefinition> input = new ArrayList<>();
        Set<String> ignored = new HashSet<>();

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertNotNull(result);
        assertTrue(result.isEmpty());
    }
}
